        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    def is_square(n):
        s = int(math.isqrt(n))
        return s*s == n
    for _ in range(1000):
        U = rng.randint(2, 30)
        V = rng.randint(2, 30)
        P = rng.randint(1, 20)
        Q = rng.randint(1, 20)
        # Prefer coprime weights
        if math.gcd(P, Q) != 1:
            continue
        S = P*U + Q*V
        if not is_square(S):
            continue
        t = int(math.isqrt(S))
        # Avoid trivial simultaneous squares for A and B
        if int(math.isqrt(U))**2 == U and int(math.isqrt(V))**2 == V:
            continue
        # Ensure non-integer final value
        N = P*P*U**3 + Q*Q*V**3
        D = t**5
        g = math.gcd(N, D)
        p_res = N // g
        q_res = D // g
        if q_res <= 1:
            continue
        # Keep lambda in (0,1) automatically since P,U,Q,V > 0 and t^2 = P*U+Q*V
        # Some mild size control to avoid absurdly huge answers
        if p_res + q_res > 10**7:
            continue
        return {
            'u': U,
            'v': V,
            't': t,
            'p_weight': P,
            'q_weight': Q
        }
    # Fallback deterministic valid instance
    U, V, P, Q = 1, 8, 1, 3
    t = int(math.isqrt(P*U + Q*V))  # sqrt(25) = 5
    return {
        'u': U,
        'v': V,
        't': t,
        'p_weight': P,
        'q_weight': Q
    }

