    den_lambda = t*t
    if not (0 < num_lambda < den_lambda):
        # Should be strictly between 0 and 1
        return (False, None)
    # Mild hardness check: avoid both A and B being rational (both squares) to force surds
    if int(math.isqrt(U))**2 == U and int(math.isqrt(V))**2 == V:
        return (False, None)
